    cls = _ACTIONS.get(d.get("action", ""))
    if cls is None:
        raise EditError(f"unknown edit action {d.get('action')!r}")
    if cls in (AddVariable,):
        return cls(_spec_from_dict(VariableSpec, d["spec"]))
    if cls in (AddFactor, ReplaceFactor):
